mapper.select:
SELECT * FROM shared_content_block

    AND status = #{status}
    AND block_type = #{blockType}

ORDER BY updated_at DESC

mapper.update:
UPDATE shared_content_block
SET status     = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM shared_content_block WHERE slug = #{slug} AND id != #{id}
)
